// argv assembly for run --mode fast|cycle. See run_passthrough.hpp.
#include "run_passthrough.hpp"

#include "argv.hpp"

namespace andes_sim {

std::vector<std::string> passthrough_argv(
    const EngineDescriptor& eng, const std::string& role, const std::string& elf,
    const std::vector<std::string>& passthrough, std::string& err) {
  const std::vector<std::string>* tmpl = eng.invoke_for(role);
  if (!tmpl) {
    err = "engine '" + eng.id + "' has no invoke template for role '" + role +
          "'";
    return {};
  }
  std::vector<std::string> argv =
      build_argv(*tmpl, {{"bin", eng.bin_path}, {"elf", elf}}, err);
  if (!err.empty()) return {};
  argv.insert(argv.end(), passthrough.begin(), passthrough.end());
  return argv;
}

}  // namespace andes_sim

// Subprocess helpers for andesim.
//
// run_process spawns a child, captures its stdout, and kills it after a
// timeout -- the primitive the engine registry uses to ask `<bin> --describe`
// and the plan executor (F6) uses to run orchestrated legs. F5 extends this
// file with exec_passthrough (inherit stdio, no timeout) for fast/cycle.
#ifndef ANDESIM_PROCESS_HPP
#define ANDESIM_PROCESS_HPP

#include <functional>
#include <string>
#include <string_view>
#include <vector>

namespace andes_sim {

struct RunResult {
  int rc = -1;                // child exit status, or -1 if killed/abnormal
  std::string out;            // captured stdout
  bool timed_out = false;     // killed because it exceeded the timeout
  bool spawn_failed = false;  // pipe/fork failed before the child ran
};

// Run argv (argv[0] resolved via PATH), capturing stdout. The child's stdin
// and stderr are redirected to /dev/null. If the child runs longer than
// timeout_ms it is SIGKILLed and timed_out is set.
RunResult run_process(const std::vector<std::string>& argv, int timeout_ms);

// Run argv to completion with the child INHERITING this process's stdout and
// stderr (its output streams straight to the terminal) and stdin from
// /dev/null; chdir to `cwd` first if non-empty. No capture, no timeout. Returns
// the child's exit code, 128+signal if it was signalled, or -1 on spawn
// failure. Used by `build` to delegate to setup.sh / build_*.sh / make.
int run_inherit(const std::vector<std::string>& argv, const std::string& cwd);

// Run argv to completion with the child INHERITING all three std streams
// (stdin, stdout, stderr) -- the transparent-passthrough mechanism behind
// `run --mode fast|cycle`: the engine reads/writes the terminal directly,
// so an interactive gdbstub or semihosting console works unchanged. No chdir,
// no capture, no timeout. Returns the child's exit code, 128+signal if it was
// signalled, or -1 on spawn failure / empty argv.
int exec_passthrough(const std::vector<std::string>& argv);

// Fork a child that execs argv with inherited stdio and return immediately
// without waiting. Used by `run --mode cycle --gdb` to launch vsim in the
// background before exec-ing ICEman in the foreground. Returns the child pid
// on success, -1 on empty argv or fork failure.
int fork_background(const std::vector<std::string>& argv);

// Run argv with BOTH stdout and stderr captured (separate pipes) and stdin
// inherited, streaming each complete line to `on_line(stream, line)` as it
// arrives -- stream is 1 (stdout) or 2 (stderr), line excludes the trailing
// newline. The callback owns presentation (it decides what to write to the real
// streams), so this is the filtered counterpart to exec_passthrough: same "run
// to completion, no timeout, propagate exit code" contract, but the parent sees
// every line. A final unterminated line is delivered too. Returns the child's
// exit code, 128+signal if signalled, or -1 on spawn failure / empty argv.
int run_line_filtered(
    const std::vector<std::string>& argv,
    const std::function<void(int stream, std::string_view line)>& on_line);

}  // namespace andes_sim

#endif  // ANDESIM_PROCESS_HPP

#include "process.hpp"

#include <cerrno>
#include <ctime>

#include <fcntl.h>
#include <poll.h>
#include <signal.h>
#include <sys/wait.h>
#include <unistd.h>

namespace andes_sim {
namespace {

long now_ms() {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;
}

// In the just-forked child: replace the image with argv (argv[0] resolved via
// PATH), or _exit(127) if exec fails. Never returns.
[[noreturn]] void exec_or_die(const std::vector<std::string>& argv) {
  std::vector<char*> cargv;
  cargv.reserve(argv.size() + 1);
  for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
  cargv.push_back(nullptr);
  execvp(cargv[0], cargv.data());
  _exit(127);  // exec failed
}

// Reap `pid` and map its wait status to an exit code: the child's exit code,
// 128+signal if it was signalled, or -1 otherwise.
int wait_for_exit_code(pid_t pid) {
  int status = 0;
  waitpid(pid, &status, 0);
  if (WIFEXITED(status)) return WEXITSTATUS(status);
  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
  return -1;
}

// fork + (optional chdir) + (optional stdin from /dev/null) + exec.
// When `wait` is true (the default) waits for the child and returns its exit
// code, 128+signal if signalled, or -1 on failure. When `wait` is false
// returns the child pid immediately without waiting (caller owns the child).
// Backs run_inherit (build: stdin closed, chdir), exec_passthrough (run
// fast/cycle: stdin inherited, no chdir), and fork_background (no wait).
int spawn_inherit(const std::vector<std::string>& argv, const std::string& cwd,
                  bool stdin_from_devnull, bool wait = true) {
  if (argv.empty()) return -1;

  pid_t pid = fork();
  if (pid < 0) return -1;

  if (pid == 0) {  // child
    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
    if (stdin_from_devnull) {
      int devnull = open("/dev/null", O_RDONLY);
      if (devnull >= 0) {
        dup2(devnull, STDIN_FILENO);
        if (devnull > 2) close(devnull);
      }
    }
    exec_or_die(argv);
  }

  if (!wait) return static_cast<int>(pid);
  return wait_for_exit_code(pid);
}

}  // namespace

RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
  RunResult r;
  if (argv.empty()) {
    r.spawn_failed = true;
    return r;
  }

  int fds[2];
  if (pipe(fds) != 0) {
    r.spawn_failed = true;
    return r;
  }

  pid_t pid = fork();
  if (pid < 0) {
    close(fds[0]);
    close(fds[1]);
    r.spawn_failed = true;
    return r;
  }

  if (pid == 0) {  // child
    close(fds[0]);
    dup2(fds[1], STDOUT_FILENO);
    int devnull = open("/dev/null", O_RDWR);
    if (devnull >= 0) {
      dup2(devnull, STDIN_FILENO);
      dup2(devnull, STDERR_FILENO);
      if (devnull > 2) close(devnull);
    }
    close(fds[1]);
    exec_or_die(argv);
  }

  // parent
  close(fds[1]);
  int rfd = fds[0];
  const long deadline = now_ms() + timeout_ms;
  char buf[4096];

  while (true) {
    long remaining = deadline - now_ms();
    if (remaining < 0) remaining = 0;
    struct pollfd pfd{rfd, POLLIN, 0};
    int pr = poll(&pfd, 1, static_cast<int>(remaining));
    if (pr < 0) {
      if (errno == EINTR) continue;
      break;
    }
    if (pr == 0) {  // timed out with no data ready
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
      ssize_t n = read(rfd, buf, sizeof(buf));
      if (n > 0) {
        r.out.append(buf, static_cast<size_t>(n));
      } else if (n == 0) {
        break;  // EOF: child closed stdout
      } else {
        if (errno == EINTR) continue;
        break;
      }
    }
    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
      kill(pid, SIGKILL);
      r.timed_out = true;
      break;
    }
  }

  close(rfd);
  int status = 0;
  waitpid(pid, &status, 0);
  // rc stays -1 (the default) when timed out or abnormally terminated.
  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
  return r;
}

int run_inherit(const std::vector<std::string>& argv, const std::string& cwd) {
  return spawn_inherit(argv, cwd, /*stdin_from_devnull=*/true);
}

int exec_passthrough(const std::vector<std::string>& argv) {
  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false);
}

int fork_background(const std::vector<std::string>& argv) {
  return spawn_inherit(argv, /*cwd=*/"", /*stdin_from_devnull=*/false, /*wait=*/false);
}

namespace {

// Drain everything readable on `fd` into `buf`, delivering each completed
// '\n'-terminated line (newline stripped) to on_line. Returns false at EOF /
// error so the caller stops polling that stream.
bool pump_stream(int fd, int stream, std::string& buf,
                 const std::function<void(int, std::string_view)>& on_line) {
  char rb[4096];
  const ssize_t n = read(fd, rb, sizeof rb);
  if (n == 0) return false;          // EOF: child closed this stream
  if (n < 0) return errno == EINTR;  // transient -> keep; real error -> stop
  buf.append(rb, static_cast<size_t>(n));
  size_t nl;
  while ((nl = buf.find('\n')) != std::string::npos) {
    on_line(stream, std::string_view(buf.data(), nl));
    buf.erase(0, nl + 1);
  }
  return true;
}

}  // namespace

int run_line_filtered(
    const std::vector<std::string>& argv,
    const std::function<void(int, std::string_view)>& on_line) {
  if (argv.empty()) return -1;

  int out_fds[2], err_fds[2];
  if (pipe(out_fds) != 0) return -1;
  if (pipe(err_fds) != 0) {
    close(out_fds[0]);
    close(out_fds[1]);
    return -1;
  }

  pid_t pid = fork();
  if (pid < 0) {
    close(out_fds[0]);
    close(out_fds[1]);
    close(err_fds[0]);
    close(err_fds[1]);
    return -1;
  }

  if (pid == 0) {  // child: stdout/stderr to the pipes, stdin inherited
    close(out_fds[0]);
    close(err_fds[0]);
    dup2(out_fds[1], STDOUT_FILENO);
    dup2(err_fds[1], STDERR_FILENO);
    if (out_fds[1] > 2) close(out_fds[1]);
    if (err_fds[1] > 2) close(err_fds[1]);
    exec_or_die(argv);
  }

  // parent: poll both pipes, line-buffer each, until both hit EOF. No timeout --
  // matches exec_passthrough (a cycle run can be arbitrarily long). The stream id
  // is index+1 (0 -> stdout=1, 1 -> stderr=2); a closed stream's fd is set to -1,
  // which poll() ignores (revents 0).
  close(out_fds[1]);
  close(err_fds[1]);
  const int fd[2] = {out_fds[0], err_fds[0]};
  std::string buf[2];
  bool open_[2] = {true, true};

  struct pollfd pfd[2] = {{fd[0], POLLIN, 0}, {fd[1], POLLIN, 0}};
  while (open_[0] || open_[1]) {
    for (int i = 0; i < 2; ++i) pfd[i].fd = open_[i] ? fd[i] : -1;
    if (poll(pfd, 2, -1) < 0) {
      if (errno == EINTR) continue;
      break;
    }
    for (int i = 0; i < 2; ++i)
      if (open_[i] && (pfd[i].revents & (POLLIN | POLLHUP | POLLERR)))
        if (!pump_stream(fd[i], i + 1, buf[i], on_line)) open_[i] = false;
  }
  // Flush any final line that arrived without a trailing newline.
  for (int i = 0; i < 2; ++i)
    if (!buf[i].empty()) on_line(i + 1, buf[i]);

  close(fd[0]);
  close(fd[1]);
  return wait_for_exit_code(pid);
}

