23	RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
24	  RunResult r;
25	  if (argv.empty()) {
26	    r.spawn_failed = true;
27	    return r;
28	  }
29	
30	  int fds[2];
31	  if (pipe(fds) != 0) {
32	    r.spawn_failed = true;
33	    return r;
34	  }
35	
36	  pid_t pid = fork();
37	  if (pid < 0) {
38	    close(fds[0]);
39	    close(fds[1]);
40	    r.spawn_failed = true;
41	    return r;
42	  }
43	
44	  if (pid == 0) {  // child
45	    close(fds[0]);
46	    dup2(fds[1], STDOUT_FILENO);
47	    int devnull = open("/dev/null", O_RDWR);
48	    if (devnull >= 0) {
49	      dup2(devnull, STDIN_FILENO);
50	      dup2(devnull, STDERR_FILENO);
51	      if (devnull > 2) close(devnull);
52	    }
53	    close(fds[1]);
54	    std::vector<char*> cargv;
55	    cargv.reserve(argv.size() + 1);
56	    for (const std::string& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
57	    cargv.push_back(nullptr);
58	    execvp(cargv[0], cargv.data());
59	    _exit(127);  // exec failed
60	  }
61	
62	  // parent
63	  close(fds[1]);
64	  int rfd = fds[0];
65	  const long deadline = now_ms() + timeout_ms;
66	  char buf[4096];
67	
68	  while (true) {
69	    long remaining = deadline - now_ms();
70	    if (remaining < 0) remaining = 0;
71	    struct pollfd pfd{rfd, POLLIN, 0};
72	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
73	    if (pr < 0) {
74	      if (errno == EINTR) continue;
75	      break;
76	    }
77	    if (pr == 0) {  // timed out with no data ready
78	      kill(pid, SIGKILL);
79	      r.timed_out = true;
80	      break;
81	    }
82	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
83	      ssize_t n = read(rfd, buf, sizeof(buf));
84	      if (n > 0) {
85	        r.out.append(buf, static_cast<size_t>(n));
86	      } else if (n == 0) {
87	        break;  // EOF: child closed stdout
88	      } else {
89	        if (errno == EINTR) continue;
90	        break;
91	      }
92	    }
93	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
94	      kill(pid, SIGKILL);
95	      r.timed_out = true;
96	      break;
97	    }
98	  }
99	
100	  close(rfd);
101	  int status = 0;
102	  waitpid(pid, &status, 0);
103	  // rc stays -1 (the default) when timed out or abnormally terminated.
104	  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
105	  return r;
106	}
