// `andes-sim run --model fast|accurate|hybrid [engine selection] ELF [-- engine args]`.
//
// The top selection axis. F7 lands `--model fast`: resolve the built-in qemu
// engine and hand off to transparent passthrough -- the ELF plus everything
// after `--` becomes QEMU's own command line, run with inherited stdio, no
// timeout, and the exit code propagated, so a gdbstub / monitor / semihosting
// console all behave as if QEMU were invoked directly. `accurate` (F8) and
// `hybrid` (F9) land in later features; their dispatch arms stub for now.
#include <cstdio>
#include <string>

#include "cli.hpp"
#include "engine_registry.hpp"
#include "models.hpp"
#include "run_passthrough.hpp"

namespace andes_sim {
namespace {

const EngineDescriptor* find_engine(const Discovery& disc, const std::string& id) {
  for (const EngineDescriptor& e : disc.engines)
    if (e.id == id) return &e;
  return nullptr;
}

// `run --model fast`: QEMU alone, functional, transparent passthrough.
int run_fast(const Cli& cli) {
  if (cli.positional.empty()) {
    std::fprintf(stderr, "andes-sim run --model fast: missing ELF\n");
    return 2;
  }
  if (cli.positional.size() > 1) {
    std::fprintf(stderr,
                 "andes-sim run --model fast: unexpected argument '%s' "
                 "(engine args go after --)\n",
                 cli.positional[1].c_str());
    return 2;
  }
  // fast is QEMU-only; an explicit engine must name it.
  if (!cli.engine.empty() && cli.engine != "qemu") {
    std::fprintf(stderr,
                 "andes-sim run --model fast: engine must be 'qemu', got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }

  Discovery disc = discover_engines();
  const EngineDescriptor* qemu = find_engine(disc, "qemu");
  if (!qemu) {
    std::fprintf(stderr, "andes-sim run --model fast: qemu engine not found\n");
    return 2;
  }

  std::string err;
  int rc = run_passthrough(*qemu, "standalone", cli.positional[0],
                           cli.passthrough, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andes-sim run: %s\n", err.c_str());
    return 2;
  }
  return rc;
}

}  // namespace

int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andes-sim run: --model fast|accurate|hybrid is required\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andes-sim run: unknown model '%s' (want fast|accurate|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);

  std::fprintf(stderr, "andes-sim run --model %s: not yet implemented\n",
               cli.model.c_str());
  return 3;
}

}  // namespace andes_sim

// Unit tests for the F7 transparent-passthrough argv assembly (run --model
// fast). passthrough_argv fills an engine's role invoke template ({bin}/{elf})
// then appends the verbatim post-`--` engine args -- the data path behind
// `run --model fast prog.elf -- -gdb tcp::1234 -S` behaving like raw QEMU.
//
// The live spawn path (run_passthrough -> exec_passthrough) is exercised
// end-to-end by tests/andes_sim/test_andes_sim_f7.sh; exec_passthrough's
// stdio-inherit + exit-code propagation is already covered by the F5 infra
// test, so this file stays pure (no spawn). Plain assert-and-count harness.
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "run_passthrough.hpp"
#include "test_check.hpp"

using namespace andes_sim;

namespace {

// The standalone template the built-in qemu descriptor ships (engine_registry):
// the andes functional config, {bin}/{elf} to be filled.
EngineDescriptor fake_qemu() {
  EngineDescriptor d;
  d.id = "qemu";
  d.bin_path = "/q";
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
        "-nographic", "-semihosting-config", "enable=on,target=native", "-bios",
        "{elf}"}});
  return d;
}

void check_eq(const std::vector<std::string>& got,
              const std::vector<std::string>& want, const char* label) {
  CHECK(got.size() == want.size());
  const size_t n = got.size() < want.size() ? got.size() : want.size();
  for (size_t i = 0; i < n; ++i) {
    if (got[i] != want[i])
      std::fprintf(stderr, "  %s[%zu]: got '%s' want '%s'\n", label, i,
                   got[i].c_str(), want[i].c_str());
    CHECK(got[i] == want[i]);
  }
}

}  // namespace

int main() {
  const EngineDescriptor q = fake_qemu();

  // The F7 done-when shape: post-`--` engine args (here a gdbstub) append
  // verbatim AFTER the filled standalone template.
  {
    std::string err;
    std::vector<std::string> got = passthrough_argv(
        q, "standalone", "/prog.elf", {"-gdb", "tcp::1234", "-S"}, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
              "-nographic", "-semihosting-config", "enable=on,target=native",
              "-bios", "/prog.elf", "-gdb", "tcp::1234", "-S"},
             "gdbstub");
  }

  // No passthrough args: just the filled template, {elf} in place.
  {
    std::string err;
    std::vector<std::string> got =
        passthrough_argv(q, "standalone", "/prog.elf", {}, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
              "-nographic", "-semihosting-config", "enable=on,target=native",
              "-bios", "/prog.elf"},
             "no-pass");
  }

  // A role the engine has no template for is an error, not a silent partial
  // argv (the caller must not spawn a half-built command line).
  {
    std::string err;
    std::vector<std::string> got =
        passthrough_argv(q, "accurate-leg", "/prog.elf", {}, err);
    CHECK(got.empty());
    CHECK(!err.empty());
  }

  return andes_sim::test::report("run");
}

// Unit tests for the pure cores of `run` (no spawn):
//   - passthrough_argv (F7): fill an engine's role invoke template ({bin}/{elf})
//     then append the verbatim post-`--` engine args -- the data path behind
//     `run --mode fast prog.elf -- -gdb tcp::1234 -S` behaving like raw QEMU.
//   - resolve_accurate_engine (F8): pick the cycle-accurate engine for
//     `run --mode cycle` (explicit --engine or the sole default; the
//     ambiguous / missing / wrong-kind error branches).
//
// The live spawn paths (fast's exec_passthrough, cycle's run_cycle_clean) are
// exercised end-to-end by tests/andes_sim/test_andes_sim_f{7,8}.sh;
// exec_passthrough's stdio-inherit + exit-code propagation is already covered by
// the F5 infra test, so this file stays pure. Plain assert-and-count harness.
#include <string>
#include <vector>

#include "engine_descriptor.hpp"
#include "engine_registry.hpp"
#include "run_passthrough.hpp"
#include "test_check.hpp"

using namespace andes_sim;
using andes_sim::test::check_eq;

namespace {

// The standalone template the built-in qemu descriptor ships (engine_registry):
// the andes functional config, {bin}/{elf} to be filled.
EngineDescriptor fake_qemu() {
  EngineDescriptor d;
  d.id = "qemu";
  d.bin_path = "/q";
  d.invoke.push_back(
      {"standalone",
       {"{bin}", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
        "-nographic", "-semihosting-config", "enable=on,target=native", "-bios",
        "{elf}"}});
  return d;
}

// A minimal engine descriptor for the resolution tests: only id + kind matter
// to resolve_accurate_engine.
EngineDescriptor eng(const std::string& id, const std::string& kind) {
  EngineDescriptor d;
  d.id = id;
  d.kind = kind;
  return d;
}

}  // namespace

int main() {
  const EngineDescriptor q = fake_qemu();

  // The F7 done-when shape: post-`--` engine args (here a gdbstub) append
  // verbatim AFTER the filled standalone template.
  {
    std::string err;
    std::vector<std::string> got = passthrough_argv(
        q, "standalone", "/prog.elf", {"-gdb", "tcp::1234", "-S"}, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
              "-nographic", "-semihosting-config", "enable=on,target=native",
              "-bios", "/prog.elf", "-gdb", "tcp::1234", "-S"},
             "gdbstub");
  }

  // No passthrough args: just the filled template, {elf} in place.
  {
    std::string err;
    std::vector<std::string> got =
        passthrough_argv(q, "standalone", "/prog.elf", {}, err);
    CHECK(err.empty());
    check_eq(got,
             {"/q", "-machine", "andes_ae350", "-cpu", "andes-ax45mpv,vlen=512",
              "-nographic", "-semihosting-config", "enable=on,target=native",
              "-bios", "/prog.elf"},
             "no-pass");
  }

  // A role the engine has no template for is an error, not a silent partial
  // argv (the caller must not spawn a half-built command line).
  {
    std::string err;
    std::vector<std::string> got =
        passthrough_argv(q, "accurate-leg", "/prog.elf", {}, err);
    CHECK(got.empty());
    CHECK(!err.empty());
  }

  // --- resolve_accurate_engine (F8): which cycle-accurate engine `cycle` runs ---
  const EngineDescriptor qemu = eng("qemu", "functional");
  const EngineDescriptor v1 = eng("vsim:ax45mpv_premium", "cycle-accurate");
  const EngineDescriptor v2 = eng("vsim:ax66_makatau", "cycle-accurate");

  // No --engine, exactly one cycle-accurate engine: that one is the default.
  {
    std::vector<EngineDescriptor> engines = {qemu, v1};
    std::string err;
    const EngineDescriptor* got = resolve_accurate_engine(engines, "", err);
    CHECK(got == &engines[1]);
    CHECK(err.empty());
  }
  // No --engine, two cycle-accurate engines: ambiguous -> error naming both.
  {
    std::vector<EngineDescriptor> engines = {qemu, v1, v2};
    std::string err;
    CHECK(resolve_accurate_engine(engines, "", err) == nullptr);
    CHECK(err.find("multiple") != std::string::npos);
    CHECK(err.find("vsim:ax45mpv_premium") != std::string::npos);
    CHECK(err.find("vsim:ax66_makatau") != std::string::npos);
  }
  // No --engine, zero cycle-accurate engines (qemu is functional): error.
  {
    std::vector<EngineDescriptor> engines = {qemu};
    std::string err;
    CHECK(resolve_accurate_engine(engines, "", err) == nullptr);
    CHECK(!err.empty());
  }
  // Explicit --engine selects that engine among several cycle-accurate ones.
  {
    std::vector<EngineDescriptor> engines = {qemu, v1, v2};
    std::string err;
    const EngineDescriptor* got =
        resolve_accurate_engine(engines, "vsim:ax66_makatau", err);
    CHECK(got == &engines[2]);
    CHECK(err.empty());
  }
  // Explicit --engine that matches no discovered engine: error.
  {
    std::vector<EngineDescriptor> engines = {qemu, v1};
    std::string err;
    CHECK(resolve_accurate_engine(engines, "vsim:nope", err) == nullptr);
    CHECK(err.find("vsim:nope") != std::string::npos);
  }
  // Explicit --engine naming a functional engine (qemu): wrong kind -> error.
  {
    std::vector<EngineDescriptor> engines = {qemu, v1};
    std::string err;
    CHECK(resolve_accurate_engine(engines, "qemu", err) == nullptr);
    CHECK(err.find("cycle-accurate") != std::string::npos);
  }

  // --- normalize_engine_label: the vsim binary self-reports the third-party
  // simulator name; the product surface speaks "vsim". One translation point so
  // every downstream consumer (list / --engine / errors / banner) sees the
  // product id.
  {  // the legacy label is rewritten in both type and the id prefix
    EngineDescriptor d = eng("verilator:ax45mpv_premium", "cycle-accurate");
    d.type = "verilator";
    normalize_engine_label(d);
    CHECK(d.type == "vsim");
    CHECK(d.id == "vsim:ax45mpv_premium");
  }
  {  // the built-in functional engine is untouched
    EngineDescriptor d = eng("qemu", "functional");
    d.type = "qemu";
    normalize_engine_label(d);
    CHECK(d.type == "qemu");
    CHECK(d.id == "qemu");
  }
  {  // a different backend passes through verbatim (only verilator is renamed)
    EngineDescriptor d = eng("alioth:x", "cycle-accurate");
    d.type = "alioth";
    normalize_engine_label(d);
    CHECK(d.type == "alioth");
    CHECK(d.id == "alioth:x");
  }

  return andes_sim::test::report("run");
}

1	// Tiny assert-and-count harness shared by the driver's standalone unit tests
2	// (cli_test, json_test, and F5+ infra tests). No doctest dependency: each test
3	// is its own executable, calls CHECK(...) for each assertion, and ends with
4	// `return andes_sim::test::report("<name>");`.
5	#ifndef ANDESIM_TEST_CHECK_HPP
6	#define ANDESIM_TEST_CHECK_HPP
7	
8	#include <cstdio>
9	#include <string>
10	#include <vector>
11	
12	namespace andes_sim::test {
13	
14	inline int g_failures = 0;
15	
16	inline int report(const char* what) {
17	  if (g_failures) {
18	    std::fprintf(stderr, "%d check(s) failed\n", g_failures);
19	    return 1;
20	  }
21	  std::printf("all %s checks passed\n", what);
22	  return 0;
23	}
24	
25	}  // namespace andes_sim::test
26	
27	#define CHECK(cond)                                                        \
28	  do {                                                                     \
29	    if (!(cond)) {                                                         \
30	      std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); \
31	      ++andes_sim::test::g_failures;                                       \
32	    }                                                                      \
33	  } while (0)
34	
35	namespace andes_sim::test {
36	
37	// Element-wise compare two string vectors: CHECK the size, then each element,
38	// printing got/want on the first mismatch. `label` tags the diff line. Shared
39	// by the driver's argv-shaped unit tests (plan_test, run_test). Defined after
40	// CHECK so the macro is in scope.
41	inline void check_eq(const std::vector<std::string>& got,
42	                     const std::vector<std::string>& want, const char* label) {
43	  CHECK(got.size() == want.size());
44	  const size_t n = got.size() < want.size() ? got.size() : want.size();
45	  for (size_t i = 0; i < n; ++i) {
46	    if (got[i] != want[i])
47	      std::fprintf(stderr, "  %s[%zu]: got '%s' want '%s'\n", label, i,
48	                   got[i].c_str(), want[i].c_str());
49	    CHECK(got[i] == want[i]);
50	  }
51	}
52	
53	}  // namespace andes_sim::test
54	
55	#endif  // ANDESIM_TEST_CHECK_HPP
