24	namespace fs = std::filesystem;
25	
26	namespace andes_sim {
27	namespace {
28	
29	std::vector<std::string> read_lines(const fs::path& p, bool& ok) {
30	  std::ifstream f(p);
31	  std::vector<std::string> lines;
32	  ok = static_cast<bool>(f);
33	  if (!ok) return lines;
34	  std::string line;
35	  while (std::getline(f, line)) lines.push_back(line);
36	  return lines;
37	}
38	
39	// Match a Makefile variable assignment at column 0: `VAR :?= <body>` where
40	// VAR is [A-Z_][A-Z0-9_]*. Mirrors the Python regex anchor. On success sets
41	// `var` and `body` (the text after `=`, continuation backslash included).
42	bool parse_assignment(const std::string& line, std::string& var,
43	                      std::string& body) {
44	  const size_t n = line.size();
45	  if (n == 0) return false;
46	  char c0 = line[0];
47	  if (!((c0 >= 'A' && c0 <= 'Z') || c0 == '_')) return false;
48	  size_t p = 0;
49	  while (p < n) {
50	    char c = line[p];
51	    if ((c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_') ++p;
52	    else break;
53	  }
54	  var = line.substr(0, p);
55	  while (p < n && (line[p] == ' ' || line[p] == '\t')) ++p;  // \s*
56	  if (p < n && line[p] == ':') ++p;                          // :?
57	  if (p >= n || line[p] != '=') return false;                // =
58	  ++p;
59	  body = line.substr(p);
60	  return true;
61	}
62	
63	struct Fixture {
64	  std::string name;
65	  std::string family;
66	};
67	
68	// Extract fixture (name, family) rows from tests/fixtures/Makefile in stable,
69	// family-grouped, file order; dedupe globally; append handoff_roundtrip last.
70	std::vector<Fixture> parse_fixtures(const std::vector<std::string>& lines) {
71	  static const std::pair<std::string, std::string> interesting[] = {
72	      {"RT_FIXTURES", "asm"},
73	      {"RT_C_FIXTURES", "c"},
74	      {"RT_C_V_FIXTURES", "c+rvv"},
75	      {"PROBE_V_FIXTURES", "probe"},
76	  };
77	  std::vector<Fixture> rows;
78	  std::set<std::string> seen;
79	
80	  for (size_t k = 0; k < lines.size(); ++k) {
81	    std::string var, body;
82	    if (!parse_assignment(lines[k], var, body)) continue;
83	    std::string family;
84	    for (const auto& it : interesting)
85	      if (it.first == var) { family = it.second; break; }
86	    if (family.empty()) continue;
87	
88	    // Splice continuation lines: a trailing backslash + newline becomes a space.
89	    size_t li = k;
90	    while (!body.empty() && body.back() == '\\') {
91	      body.pop_back();
92	      body.push_back(' ');
93	      if (++li < lines.size()) body += lines[li];
94	      else break;
95	    }
96	
97	    std::istringstream iss(body);
98	    std::string name;
99	    while (iss >> name)
100	      if (seen.insert(name).second) rows.push_back({name, family});
101	  }
102	
103	  // handoff_roundtrip is not in a *_FIXTURES var; list it explicitly.
104	  if (seen.insert("handoff_roundtrip").second)
105	    rows.push_back({"handoff_roundtrip", "asm"});
106	
107	  return rows;
108	}
109	
110	int list_fixtures() {
111	  fs::path mk = repo_root() / "tests" / "fixtures" / "Makefile";
112	  bool ok;
113	  std::vector<std::string> lines = read_lines(mk, ok);
114	  if (!ok) {
115	    std::fprintf(stderr, "andesim: missing %s\n", mk.c_str());
116	    return 2;
117	  }
118	  std::vector<Fixture> rows = parse_fixtures(lines);
119	
120	  size_t width = 0;
121	  for (const Fixture& r : rows) width = std::max(width, r.name.size());
122	
123	  std::printf("%s  FAMILY\n", ljust("FIXTURE", width).c_str());
124	  for (const Fixture& r : rows)
125	    std::printf("%s  %s\n", ljust(r.name, width).c_str(), r.family.c_str());
126	  return 0;
127	}
128	
129	int list_models() {
130	  size_t wn = 5, we = 7;  // header widths: MODEL, ENGINES
131	  for (const Model& m : kModels) {
132	    wn = std::max(wn, m.name.size());
133	    we = std::max(we, m.engines.size());
134	  }
135	  std::printf("%s  %s  NOTES\n", ljust("MODEL", wn).c_str(),
136	              ljust("ENGINES", we).c_str());
137	  for (const Model& m : kModels)
138	    std::printf("%s  %s  %s\n", ljust(std::string(m.name), wn).c_str(),
139	                ljust(std::string(m.engines), we).c_str(),
140	                std::string(m.notes).c_str());
141	  return 0;
142	}
143	
144	int list_engines() {
145	  Discovery disc = discover_engines();
146	
147	  // Columns describe engine identity only. Triggers are a hybrid-MODEL option
148	  // (see `list models` / `run --help`), not an engine attribute, so no TRIGGERS
149	  // column here.
150	  size_t we = 6, wt = 4, wk = 4;  // ENGINE, TYPE, KIND headers
151	  for (const EngineDescriptor& e : disc.engines) {
152	    we = std::max(we, e.id.size());
153	    wt = std::max(wt, e.type.size());
154	    wk = std::max(wk, e.kind.size());
155	  }
156	
157	  std::printf("%s  %s  %s  VLEN\n", ljust("ENGINE", we).c_str(),
158	              ljust("TYPE", wt).c_str(), ljust("KIND", wk).c_str());
159	  for (const EngineDescriptor& e : disc.engines)
160	    std::printf("%s  %s  %s  %s\n", ljust(e.id, we).c_str(),
161	                ljust(e.type, wt).c_str(), ljust(e.kind, wk).c_str(),
162	                vlen_str(e.vlen).c_str());
163	
164	  // Binaries that could not self-describe are reported, never silently dropped.
165	  for (const std::string& w : disc.warnings)
166	    std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
167	  return 0;
168	}
