172	int cmd_list(const Cli& cli) {
173	  // `fixtures` lists internal test ELFs -- a developer target, gated behind
174	  // ANDESIM_DEV so the release product offers only user-facing models/engines.
175	  const char* targets = is_dev_mode() ? "fixtures|models|engines" : "models|engines";
176	  if (cli.positional.empty()) {
177	    std::fprintf(stderr, "andesim list: expected one of %s\n", targets);
178	    return 2;
179	  }
180	  const std::string& t = cli.positional[0];
181	  if (t == "fixtures" && is_dev_mode()) return list_fixtures();
182	  if (t == "models") return list_models();
183	  if (t == "engines") return list_engines();
184	  std::fprintf(stderr, "andesim list: unknown target '%s' (want %s)\n",
185	               t.c_str(), targets);
186	  return 2;
187	}
